WITH valid_accounts AS (SELECT *, LOWER(account_type) AS account_type_lower FROM accounts WHERE opened_date BETWEEN '2023-11-28' AND '2025-03-01' AND opened_date BETWEEN '2023-08-01' AND '2024-05-01'), summary AS (SELECT DATE_TRUNC('MONTH', opened_date) AS opened_month, ROUND(STDDEV(balance), 2) AS stddev_balance FROM valid_accounts GROUP BY DATE_TRUNC('MONTH', opened_date)) SELECT * FROM summary WHERE stddev_balance > 34 ORDER BY stddev_balance, opened_month DESC;
